<script setup lang="ts">import { computed } from "vue"; import { useRoute } from "vue-router"; import BottomNav from "./components/navigation/BottomNav.vue"; import PortalLayout from "./components/portal/PortalLayout.vue"; const route = useRoute(); const isPortal = computed(() => String(route.path).startsWith("/zh")); const isNewPortal = computed(() => ["portal-home", "portal-games", "portal-game-detail", "portal-favorites", "crazygames-hot-metadata"].includes(String(route.name))); const hideNavigation = computed(() => route.meta.hideNavigation === true);</script><template><PortalLayout v-if="isPortal && !isNewPortal" :immersive="route.meta.immersive === true"><RouterView /></PortalLayout><RouterView v-else-if="isNewPortal" /><div v-else class="rpg-shell" :class="{ 'battle-shell': hideNavigation }"><main class="app-main"><RouterView /></main><BottomNav v-if="!hideNavigation" /></div></template>
